      '딜티아젬 240 mg 1일 1회 → AUC 비율 1.51, Cmax 비율 1.00',
      '에리트로마이신 500 mg 1일 4회 → AUC 비율 1.33, Cmax 비율 1.38',
      '암로디핀 10 mg 단회 → AUC 비율 1.18, Cmax 비율 0.91',
      '시메티딘 300 mg 1일 4회 → AUC 비율 1.00, Cmax 비율 0.89',
