      '이 약은 혈액투석에 의해 혈장에서 효과적으로 제거된다. (4시간 이내에 50%정도). 혈액투석을 하는 환자에서 프레가발린의 1일 투여용량은 신기능에 근거하여 조정되어야 한다. 신기능에 따른 1일 투여용량 외에 매 4시간 마다 혈액투석을 실시한 후에는 추가로 보충 용량을 즉시 투여하여야 한다.',
      '[표1]. 신기능에 근거한 프레가발린의 용량 적용',
