      '※ 아토르바스타틴 단독투여시 대비 아토르바스타틴과 병용약물 투여시의 비율. 리팜피신의 이중 상호작용 기전 때문에 아토르바스타틴과 리팜피신을 병용투여시 동시에 투여하는 것이 권장되며, 리팜피신 투여 후 아토르바스타틴을 나중에 투여하면 아토르바스타틴의 혈장 농도가 유의미하게 감소한다.',
      '[아토르바스타틴이 병용약물의 약동학에 미치는 영향 — 주요 데이터]',
