      '아토르바스타틴 40 mg 1일 1회 22일간 / 경구피임제(노르에티스테론 1 mg, 에티닐에스트라디올 35 μg) 1일 1회 2달간: 노르에티스테론 AUC 비율 1.28배, 에티닐에스트라디올 AUC 비율 1.19배',
