      '6. 임부 및 수유부에 대한 투여',
      '1) 이 약의 아토르바스타틴 성분으로 인해 임부 또는 임신하고 있을 가능성의 여성에 사용을 금한다. 임신할 가능성이 있는 여성은 적절한 피임법을 강구하여야 한다. 콜레스테롤과 그 파생물질은 배아의 성장에 매우 중요하므로 HMG-CoA 환원제 억제의 잠재적인 위험이 임신기간 동안 스타틴 치료로부터 기대되는 혜택보다 더 크다. 치료 도중에 임신사실이 발견되면 즉시 치료를 중지시키고 태아에 대한 위험성을 알려야 한다.',
      '2) 이 약의 아토르바스타틴 성분으로 인해 수유부에 사용을 금한다. 이 약을 복용중인 여성은 수유를 해서는 안된다.',
      '3) 임부 및 수유부에 대한 암로디핀의 안전성은 확립되지 않았다. 인체에 대한 권장 최대용량의 50배에 해당하는 용량의 암로디핀을 투여한 랫드에서 분만지연 및 연장이 나타난 것 외에 동물에 있어서 생식독성은 증명되지 않았다. 따라서, 임부에 대한 투여는 다른 안전한 대체약물이 없는 경우 및 질환 자체가 모체 및 태아에 큰 위험을 줄 경우에만 투여가 권장된다.',
      '7. 소아에 대한 투여',
      '이 약은 소아에 대한 안전성 및 유효성이 확립되어 있지 않다.',
      '8. 고령자에 대한 투여',
      '이 약은 고령자에 대한 안전성 및 유효성이 확립되어 있지 않다.',
      '1) 암로디핀: 일반적인 용량을 투여하는 것이 권장된다. 암로디핀을 고령자 및 젊은 연령의 환자에게 비슷한 용량으로 투여 시, 내약성이 동일하게 양호하다.',
      '2) 아토르바스타틴: 65세 이상의 건강한 노인의 경우 아토르바스타틴의 혈장농도는 젊은 성인군에 비해 더 높게 나타났으나(Cmax 40% 증가, AUC 30% 증가), LDL-콜레스테롤 저하효과는 젊은 성인군과 유사하였다.',
      '9. 과량투여시의 처치',
      '이 약을 인체에 과량 투여한 자료는 없다. 암로디핀 및 아토르바스타틴의 광범위한 혈장 단백결합 때문에, 혈액투석이 암로디핀/아토르바스타틴의 청소율에 유의하게 도움을 주는 것 같지는 않다.',
      '1) 암로디핀: 심한 과량투여 시 과도한 말초혈관확장과 함께 반사성 빈맥도 나타날 수 있다. 건강한 지원자에게 암로디핀 10 mg을 투여한 즉시 혹은 2시간 후까지 약용탄(activated charcoal)을 투여하였을 때 암로디핀의 흡수가 유의하게 감소되었다. 임상적으로 심각한 저혈압은 심장과 호흡기능을 자주 모니터링 하고, 사지의 위치를 몸체보다 높게 유지하여 혈액 등과 같은 순환체액 및 요배설량을 충분히 확보하는 등의 적극적인 심혈관계에 대한 보조요법을 필요로 한다.',
      '2) 아토르바스타틴: 아토르바스타틴 과량복용에 적용할 수 있는 특별한 처치방법은 없다. 과량복용 시 환자는 반드시 증상적으로 치료하여야 하며 필요 시 대증요법을 시행하여야 한다. 간기능 검사 및 혈청 CK치를 모니터링하여야 한다.',
      '10. 기타 (전임상 자료)',
      '1) 발암성: (1) 암로디핀: 암로디핀 0.5, 1.25, 2.5 mg/kg/day을 2년 동안 투여한 랫드 및 마우스에서 발암성의 증거는 나타나지 않았다. (2) 아토르바스타틴: kg당 mg으로 환산한 체중 기준으로 인체의 최고용량의 63배 용량으로 투여한 랫드 실험에서 발암성이 없었다.',
      '2) 돌연변이성: (1) 암로디핀: 돌연변이 시험에서 이 약은 유전자 혹은 염색체 수치에 영향을 미치지 않았다. (2) 아토르바스타틴: 4종의 시험관내 시험 및 1종의 인체내 시험에서 이 약은 대사활동의 여부에 관계없이 돌연변이 가능성을 보이지 않았다.',
      '3) 생식능력 이상: (1) 암로디핀: 10 mg/kg/day 용량까지의 암로디핀으로 처치한 랫드에서 생식능력에 대한 영향은 나타나지 않았다. (2) 아토르바스타틴: 아토르바스타틴을 최고 175 mg/kg/day까지 투여한 랫드에서 수태능 혹은 생식능에 부정적인 영향은 없었다.',
      '4) 중추신경계 독성: 아토르바스타틴 — 이 계열의 화학적으로 유사한 약물을 투여한 개에서 용량 의존적으로 시신경변성을 유발한다. 120 mg/kg/day로 3개월간 투여한 암컷 개에서 뇌출혈이 관찰되었다.',
      '11. 보관 및 취급상의 주의사항',
      '1) 어린이의 손이 닿지 않는 곳에 보관한다.',
      '2) 다른 용기에 바꾸어 넣는 것은 사고원인이 되거나 품질유지면에서 바람직하지 않으므로 이를 주의한다.',
